#include <btBulletDynamicsCommon.h>
#include <components/nif/niffile.hpp>
#include <components/nif/physics.hpp>
#include <components/nifbullet/actorragdoll.hpp>
#include <components/nifbullet/actorragdollphysics.hpp>
#include <components/nifbullet/nativedynamicsworld.hpp>
#include <components/nifbullet/ragdollvelocity.hpp>
#include <BulletCollision/CollisionShapes/btBvhTriangleMeshShape.h>
#include <BulletCollision/CollisionShapes/btTriangleMesh.h>
#include <BulletDynamics/Dynamics/btDiscreteDynamicsWorld.h>
#include <BulletDynamics/Dynamics/btRigidBody.h>
#include <BulletDynamics/ConstraintSolver/btSequentialImpulseConstraintSolver.h>
#include <fstream>
#include <iostream>
#include <iomanip>
#include <cmath>
#include <components/nifbullet/nativecompoundcollision.hpp>
#include <limits>
int main(int argc,char**argv){
 if(argc!=3)return 2;
 Nif::NIFFile file(VFS::Path::toNormalized(argv[1]));Nif::Reader reader(file,nullptr);reader.parse(std::make_unique<std::ifstream>(argv[1],std::ios::binary));auto graph=NifBullet::loadWeaponReferenceRagdollDefinition(file);
 const auto* source=dynamic_cast<const Nif::bhkRigidBody*>(file.mRecords[7].get());if(!source)return 3;
 std::cerr<<"quality="<<int(source->mInfo.mQualityType)<<" penetration="<<source->mInfo.mPenetrationDepth<<" mass="<<source->mInfo.mMass<<"\n";
 btDefaultCollisionConfiguration config;btCollisionDispatcher dispatch(&config);btDbvtBroadphase broad;btSequentialImpulseConstraintSolver solver;NifBullet::NativeDynamicsWorld world(&dispatch,&broad,&solver,&config);world.setGravity(btVector3(0,0,0));
 btTriangleMesh mesh;mesh.addTriangle({-1000,-1000,0},{1000,-1000,0},{1000,1000,0});mesh.addTriangle({-1000,-1000,0},{1000,1000,0},{-1000,1000,0});btBvhTriangleMeshShape floorShape(&mesh,true);btCollisionObject floor;floor.setCollisionShape(&floorShape);floor.setWorldTransform(btTransform::getIdentity());world.addCollisionObject(&floor,1,257);
 // Supplied initial rotation is copied from the read-only actual drop trace.
 btMatrix3x3 rotation;std::ifstream input(argv[2]);for(int i=0;i<3;++i)for(int j=0;j<3;++j)input>>rotation[i][j];if(!input)return 4;
 const std::array<btTransform,1> poses{btTransform(rotation,{0,0,103})};
 {NifBullet::ActorRagdollPhysics physics(graph,world,NifBullet::RagdollNativeLengthScale,poses,257,319);
 for(auto* p:physics.collisionObjects()){auto* body=btRigidBody::upcast(p);const auto r=NifBullet::centeredCompoundSweepRadius(*body->getCollisionShape());std::cerr<<"CCD radius "<<r<<"\n";body->setCcdMotionThreshold(std::numeric_limits<float>::epsilon());body->setCcdSweptSphereRadius(r);body->setFlags(body->getFlags()|BT_DISABLE_WORLD_GRAVITY);body->setGravity({0,0,0});}
 for(auto* p:physics.collisionObjects()){btVector3 lo,hi;p->getCollisionShape()->getAabb(p->getWorldTransform(),lo,hi);std::cerr<<"initial AABB "<<lo.x()<<','<<lo.y()<<','<<lo.z()<<" -> "<<hi.x()<<','<<hi.y()<<','<<hi.z()<<" group "<<p->getBroadphaseHandle()->m_collisionFilterGroup<<" mask "<<p->getBroadphaseHandle()->m_collisionFilterMask<<" flags "<<p->getCollisionFlags()<<" shape "<<p->getCollisionShape()->getName()<<"\n";}
 const float dt=.05f;const std::array delta{NifBullet::ragdollNativeGravityDelta({0,0,NifBullet::RagdollNativeDefaultGravityZ},dt)};
 std::cout<<std::setprecision(12);for(int frame=0;frame<600;++frame){physics.applyNativeVelocityStep(dt,delta);world.stepSimulation(dt,0);const auto s=physics.capture().front();if(frame<25)std::cerr<<"frame "<<frame<<" contacts "<<dispatch.getNumManifolds()<<" pairs "<<broad.getOverlappingPairCache()->getNumOverlappingPairs()<<'\n';std::cout<<frame<<' '<<s.mPose.getOrigin().z()<<' '<<s.mLinearVelocity.z()<<'\n';}
 }
 world.removeCollisionObject(&floor);
}
